begin;
update public.questions set subject = 'Economy', topic = 'Financial Markets, Instruments & Fintech', type = 'statement_based', difficulty = 'medium', body = 'With reference to digital payments and digital lending in India, consider the following statements:', body_hi = 'भारत में डिजिटल भुगतान और डिजिटल ऋण के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. A default loss guarantee lets a lending app or other fintech share the first losses on loans it sources for a regulated lender; the RBI''s 2023 guidelines allow it but cap it at 5 per cent of the portfolio and require it to be backed by cash, a fixed deposit or a bank guarantee, so that the fintech keeps ''skin in the game'' without the lender passing on its credit risk entirely. UPI payments carried no merchant discount rate from 2020, with an incentive scheme compensating banks; after Parliament amended Section 10A of the Payment and Settlement Systems Act in 2026, an MDR of 0.4 per cent, capped at ₹300, was approved for person-to-merchant payments above ₹2,000 -- due from 15 October 2026 but deferred by NPCI until after Diwali -- while smaller merchant payments and person-to-person transfers stay free. Statement 3 is wrong: the NPCI was set up in 2008 as a not-for-profit company, promoted by banks under the guidance of the RBI and the Indian Banks'' Association; it is regulated by the RBI under the Payment and Settlement Systems Act. It has also set a 30 per cent cap on the share of UPI volume any single third-party app may handle, though the deadline for compliance has been extended.', explanation_hi = 'कथन 1 और 2 सही हैं। चूक हानि गारंटी किसी ऋण ऐप या अन्य फ़िनटेक को किसी विनियमित ऋणदाता के लिए लाए गए ऋणों पर पहली हानियों में हिस्सा लेने देती है; आरबीआई के 2023 के दिशानिर्देश इसकी अनुमति देते हैं पर इसे पोर्टफ़ोलियो के 5 प्रतिशत तक सीमित करते हैं और नक़द, सावधि जमा या बैंक गारंटी से समर्थित होना अनिवार्य करते हैं, ताकि फ़िनटेक का दाँव बना रहे पर ऋणदाता अपना ऋण जोखिम पूरी तरह आगे न बढ़ा दे। 2020 से यूपीआई भुगतानों पर कोई मर्चेंट डिस्काउंट रेट नहीं था, और एक प्रोत्साहन योजना बैंकों की क्षतिपूर्ति करती थी; 2026 में संसद द्वारा भुगतान और निपटान प्रणाली अधिनियम की धारा 10क में संशोधन के बाद ₹2,000 से अधिक के व्यक्ति-से-व्यापारी भुगतानों पर 0.4 प्रतिशत, अधिकतम ₹300, का एमडीआर स्वीकृत हुआ -- जिसे 15 अक्टूबर 2026 से लागू होना था पर एनपीसीआई ने दिवाली के बाद तक टाल दिया -- जबकि छोटे व्यापारी भुगतान और व्यक्ति-से-व्यक्ति अंतरण निःशुल्क रहते हैं। कथन 3 ग़लत है: एनपीसीआई 2008 में आरबीआई और भारतीय बैंक संघ के मार्गदर्शन में बैंकों द्वारा प्रवर्तित एक गैर-लाभकारी कंपनी के रूप में स्थापित हुआ; यह भुगतान और निपटान प्रणाली अधिनियम के अंतर्गत आरबीआई द्वारा विनियमित है। इसने किसी एक तृतीय-पक्ष ऐप द्वारा संभाले जा सकने वाले यूपीआई लेन-देन के हिस्से पर 30 प्रतिशत की सीमा भी तय की है, हालाँकि अनुपालन की समय-सीमा बढ़ा दी गई है।', concept_group_id = 'l3-t5-eco-dlg-zero-mdr-npci-status', source_citation = 'Reserve Bank of India, Guidelines on Default Loss Guarantee in Digital Lending (2023); Payment and Settlement Systems Act, 2007, section 10A; Department of Financial Services, FAQs on MDR on UPI (P2M) transactions (2026); NPCI, deferment of MDR on select P2M transactions (October 2026); National Payments Corporation of India.', question_data = '{"statements": ["Under the RBI''s rules, a default loss guarantee given by a fintech partner to a bank or NBFC in digital lending is capped at 5 per cent of the loan portfolio.", "No merchant discount rate is charged on UPI payments to merchants of up to ₹2,000.", "The National Payments Corporation of India, which runs UPI, is a statutory body set up by an Act of Parliament."], "statements_hi": ["आरबीआई के नियमों के अंतर्गत डिजिटल ऋण में किसी फ़िनटेक साझेदार द्वारा बैंक या एनबीएफ़सी को दी गई चूक हानि गारंटी ऋण पोर्टफ़ोलियो के 5 प्रतिशत तक सीमित है।", "व्यापारियों को ₹2,000 तक के यूपीआई भुगतानों पर कोई मर्चेंट डिस्काउंट रेट नहीं लिया जाता।", "यूपीआई चलाने वाला भारतीय राष्ट्रीय भुगतान निगम संसद के अधिनियम द्वारा स्थापित सांविधिक निकाय है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id in ('l3-t5-eco-dlg-zero-mdr-npci-status') returning concept_group_id;
commit;
